mapper.select:
SELECT *
FROM dc_customer_tracking
WHERE del_flag = 0

    AND create_by = #{userId}


    AND YEAR(create_time) = #{year}


    AND MONTH(create_time) = #{month}


    AND DAY(create_time) = #{day}


    AND tracking_type = #{trackingType}


    AND cumtomer_status = #{customerStatus}


    AND is_return = #{isReturn}


    GROUP BY customer_id
